private val PrimaryBlue = Color(0xFF1565C0)
private fun money(v: Double) = if (v % 1.0 == 0.0) v.toInt().toString() else String.format(Locale.US, "%.2f", v)
private fun today() = SimpleDateFormat("yyyy-MM-dd", Locale.US).format(Date())
private fun now() = SimpleDateFormat("HH:mm", Locale.US).format(Date())
private fun safeName(value: String) = value.replace(Regex("[^\\p{L}\\p{N}_-]"), "_").take(40).ifBlank { "ملف" }

class MainActivity : ComponentActivity() { override fun onCreate(state: Bundle?) { super.onCreate(state); setContent { AziziApp() } } }

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun AziziApp() {
    val ctx = LocalContext.current; val act = ctx as Activity; val db = remember { AppDatabase.get(ctx) }; val scope = rememberCoroutineScope(); val prefs = remember { ctx.getSharedPreferences("azizi_settings", Context.MODE_PRIVATE) }
    var tab by remember { mutableStateOf("الفاتورة") }; var dark by remember { mutableStateOf(prefs.getBoolean("dark", false)) }; var storeName by remember { mutableStateOf(prefs.getString("storeName", "بقالة العزي للمواد الغذائية") ?: "بقالة العزي للمواد الغذائية") }; var storePhone by remember { mutableStateOf(prefs.getString("storePhone", "") ?: "") }
    var invoiceNo by remember { mutableIntStateOf(db.nextInvoice()) }; var customer by remember { mutableStateOf("عميل نقدي") }; var phone by remember { mutableStateOf("") }; var payment by remember { mutableStateOf("نقدي") }; var itemName by remember { mutableStateOf("") }; var qty by remember { mutableStateOf("1") }; var totalInput by remember { mutableStateOf("") }; var lines by remember { mutableStateOf(emptyList<SaleLine>()) }
    var invoices by remember { mutableStateOf(emptyList<InvoiceRow>()) }; var customers by remember { mutableStateOf(emptyList<CustomerRow>()) }; var inventory by remember { mutableStateOf(emptyList<ItemRow>()) }; var settingsOpen by remember { mutableStateOf(false) }; var customerOpen by remember { mutableStateOf(false) }; var selectedCustomer by remember { mutableStateOf<CustomerRow?>(null) }; var printerOpen by remember { mutableStateOf(false) }; var printers by remember { mutableStateOf(emptyList<BluetoothDevice>()) }
    fun refresh() { scope.launch(Dispatchers.IO) { val i=db.invoices(); val c=db.customers(); val p=db.items(); withContext(Dispatchers.Main){ invoices=i; customers=c; inventory=p } } }
    LaunchedEffect(Unit){ refresh() }; LaunchedEffect(printerOpen){ if(printerOpen) printers=withContext(Dispatchers.IO){NativeServices.pairedPrinters(act)} }
    val contactPicker=rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()){ result -> if(result.resultCode==Activity.RESULT_OK){ val uri=result.data?.data ?: return@rememberLauncherForActivityResult; try{ ctx.contentResolver.query(uri,arrayOf(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER),null,null,null)?.use{cursor->if(cursor.moveToFirst()){customer=cursor.getString(0) ?: "";phone=cursor.getString(1) ?: "";customerOpen=true}} }catch(_:Exception){Toast.makeText(ctx,"تعذر قراءة جهة الاتصال",Toast.LENGTH_SHORT).show()} } }
    fun importContact(){ contactPicker.launch(Intent(Intent.ACTION_PICK).apply{type=ContactsContract.CommonDataKinds.Phone.CONTENT_TYPE}) }
    fun saveInvoice(){ if(lines.isEmpty()){Toast.makeText(ctx,"أضف صنفاً أولاً",Toast.LENGTH_SHORT).show();return}; val number=invoiceNo; val total=lines.sumOf{it.total}; scope.launch(Dispatchers.IO){db.addInvoice(number,customer,phone,total,payment,today(),now(),lines);withContext(Dispatchers.Main){Toast.makeText(ctx,"تم تأكيد وحفظ الفاتورة رقم $number",Toast.LENGTH_SHORT).show();invoiceNo=db.nextInvoice();lines=emptyList();customer="عميل نقدي";phone="";payment="نقدي";itemName="";qty="1";totalInput="";refresh()}} }
    fun customerSaved(name:String,customerPhone:String){val clean=name.trim();if(clean.isBlank()||clean=="عميل نقدي"){Toast.makeText(ctx,"اكتب اسم العميل",Toast.LENGTH_SHORT).show();return};scope.launch(Dispatchers.IO){db.addCustomer(clean,customerPhone);withContext(Dispatchers.Main){customer=clean;phone=customerPhone;customerOpen=false;refresh();Toast.makeText(ctx,"تم حفظ العميل $clean",Toast.LENGTH_SHORT).show()}}}
    MaterialTheme(colorScheme=if(dark)darkColorScheme() else lightColorScheme(primary=PrimaryBlue)){ CompositionLocalProvider(androidx.compose.ui.platform.LocalLayoutDirection provides LayoutDirection.Rtl){ Scaffold(
        topBar={TopAppBar(title={Column{Text(storeName,fontWeight=FontWeight.Bold,fontSize=12.sp);Text("نقطة بيع ومحاسبة",fontSize=7.sp)}},actions={IconButton(onClick={tab="التقارير"}){Icon(Icons.Default.Assessment,"التقارير",modifier=Modifier.size(20.dp))};IconButton(onClick={settingsOpen=true}){Icon(Icons.Default.Settings,"الإعدادات",modifier=Modifier.size(20.dp))}})},
        bottomBar={NavigationBar{listOf("الفاتورة" to Icons.Default.ReceiptLong,"الفواتير" to Icons.Default.History,"العملاء" to Icons.Default.People,"الأصناف" to Icons.Default.Inventory,"التقارير" to Icons.Default.Assessment).forEach{(title,icon)->NavigationBarItem(selected=tab==title,onClick={tab=title},icon={Icon(icon,title,modifier=Modifier.size(20.dp))},label={Text(title,fontSize=8.sp)})}}}
    ){padding->Box(Modifier.padding(padding).fillMaxSize()){
        when(tab){
            "الفاتورة"->InvoiceScreen(invoiceNo,customer,phone,payment,itemName,qty,totalInput,lines,inventory,{customer=it},{phone=it},{payment=it},{itemName=it},{qty=it},{totalInput=it},{lines=it},::saveInvoice,{customerOpen=true},{printerOpen=true},{val b=NativeServices.receiptBitmap(invoiceNo,storeName,customer,lines,lines.sumOf{it.total},payment);val u=NativeServices.saveFile(act,b.pngBytes(),"فاتورة_${invoiceNo}_58mm.png","image/png");NativeServices.share(act,u,"image/png","فاتورة رقم $invoiceNo - $customer")},{val text="فاتورة رقم $invoiceNo\nالمتجر: $storeName\nالعميل: $customer\nالجوال: $phone\nالتاريخ: ${today()} ${now()}\nطريقة الدفع: $payment\nالإجمالي: ${money(lines.sumOf{it.total})} ر.ي";val u=NativeServices.pdf(act,"فاتورة_${invoiceNo}",text);NativeServices.share(act,u,"application/pdf",text)},{val b=NativeServices.receiptBitmap(invoiceNo,storeName,customer,lines,lines.sumOf{it.total},payment);val u=NativeServices.saveFile(act,b.pngBytes(),"فاتورة_${invoiceNo}_58mm.png","image/png");NativeServices.shareWhatsApp(act,u,"image/png","فاتورة رقم $invoiceNo - $customer")})
            "الفواتير"->HistoryScreen(invoices,{v->val text="فاتورة رقم ${v.number}\nالمتجر: $storeName\nالعميل: ${v.customer}\nالجوال: ${v.phone}\n${v.date} ${v.time}\nالإجمالي: ${money(v.total)} ر.ي\nالدفع: ${v.payment}";val u=NativeServices.pdf(act,"فاتورة_${v.number}",text);NativeServices.share(act,u,"application/pdf",text)},{v->val text="فاتورة رقم ${v.number} - ${v.customer}\nالإجمالي: ${money(v.total)} ر.ي";val b=NativeServices.receiptBitmap(v.number,storeName,v.customer,emptyList(),v.total,v.payment);val u=NativeServices.saveFile(act,b.pngBytes(),"فاتورة_${v.number}_58mm.png","image/png");NativeServices.shareWhatsApp(act,u,"image/png",text)}){val rows=listOf(listOf("رقم","العميل","الهاتف","الإجمالي","الدفع","التاريخ"))+invoices.map{listOf(it.number.toString(),it.customer,it.phone,it.total.toString(),it.payment,"${it.date} ${it.time}")};val u=NativeServices.xlsx(act,"سجل_الفواتير",rows);NativeServices.share(act,u,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")}
            "العملاء"->CustomersScreen(customers,{selectedCustomer=it},{customer="";phone="";customerOpen=true})
            "الأصناف"->InventoryScreen(inventory,db,::refresh)
            "التقارير"->ReportsScreen(invoices,customers,inventory,storeName)
        }
        if(customerOpen)CustomerDialog(customers,customer,phone,::customerSaved,::importContact){customerOpen=false}
        selectedCustomer?.let{c->LedgerDialog(act,db,c,storeName){selectedCustomer=null;refresh()}}
        if(settingsOpen)SettingsDialog(storeName,storePhone,dark,{n,p,d->storeName=n.ifBlank{"بقالة العزي للمواد الغذائية"};storePhone=p;dark=d;prefs.edit().putString("storeName",storeName).putString("storePhone",p).putBoolean("dark",d).apply();settingsOpen=false},{settingsOpen=false;printerOpen=true}){settingsOpen=false}
        if(printerOpen)PrinterDialog(printers,{printerOpen=false}){device->printerOpen=false;if(lines.isEmpty())Toast.makeText(ctx,"لا توجد أصناف للطباعة",Toast.LENGTH_SHORT).show()else{val b=NativeServices.receiptBitmap(invoiceNo,storeName,customer,lines,lines.sumOf{it.total},payment);NativeServices.printBluetooth(act,device,b){r->act.runOnUiThread{Toast.makeText(ctx,if(r=="ok")"تمت الطباعة بنجاح" else "فشل الطباعة: $r",Toast.LENGTH_LONG).show()}}}}
    }} }
}
}
private fun android.graphics.Bitmap.pngBytes():ByteArray{val out=java.io.ByteArrayOutputStream();compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);return out.toByteArray()}

@Composable private fun InvoiceScreen(invoiceNo:Int,customer:String,phone:String,payment:String,itemName:String,qty:String,totalInput:String,rows:List<SaleLine>,inventory:List<ItemRow>,setCustomer:(String)->Unit,setPhone:(String)->Unit,setPayment:(String)->Unit,setName:(String)->Unit,setQty:(String)->Unit,setTotal:(String)->Unit,setRows:(List<SaleLine>)->Unit,save:()->Unit,chooseCustomer:()->Unit,print:()->Unit,shareImage:()->Unit,sharePdf:()->Unit,shareWhatsApp:()->Unit){val grand=rows.sumOf{it.total};val shape=RoundedCornerShape(16.dp);Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(8.dp)){
    Row(horizontalArrangement=Arrangement.spacedBy(4.dp),modifier=Modifier.fillMaxWidth()){StatCard("الإجمالي",money(grand),Modifier.weight(1f));StatCard("الأصناف",rows.size.toString(),Modifier.weight(1f));StatCard("رقم",invoiceNo.toString(),Modifier.weight(1f))}
    Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Column(Modifier.padding(8.dp)){SectionTitle(Icons.Default.Person,"العميل");Row(verticalAlignment=Alignment.CenterVertically){OutlinedTextField(customer,setCustomer,label={Text("اسم العميل",fontSize=12.sp)},modifier=Modifier.weight(1f),shape=shape,singleLine=true,textStyle=LocalTextStyle.current.copy(fontSize=13.sp));IconButton(onClick=chooseCustomer){Icon(Icons.Default.PersonAdd,"اختيار العميل",modifier=Modifier.size(20.dp))}};OutlinedTextField(phone,setPhone,label={Text("رقم الجوال / واتساب",fontSize=12.sp)},modifier=Modifier.fillMaxWidth(),shape=shape,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Phone),singleLine=true,textStyle=LocalTextStyle.current.copy(fontSize=13.sp));Row(horizontalArrangement=Arrangement.spacedBy(5.dp)){FilterChip(selected=payment=="نقدي",onClick={setPayment("نقدي")},label={Text("نقدي",fontSize=11.sp)});FilterChip(selected=payment=="آجل",onClick={setPayment("آجل")},label={Text("آجل",fontSize=11.sp)})}}}
    Card(Modifier.fillMaxWidth()){Column(Modifier.padding(8.dp)){SectionTitle(Icons.Default.AddShoppingCart,"إضافة صنف بسرعة");if(inventory.isNotEmpty()){Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(4.dp)){inventory.take(8).forEach{item->AssistChip(onClick={setName(item.name);setTotal(money(item.price*(qty.toDoubleOrNull()?:1.0)))},label={Text(item.name,maxLines=1,fontSize=10.sp)},leadingIcon={Icon(Icons.Default.Inventory2,null,modifier=Modifier.size(16.dp))})}};Spacer(Modifier.height(4.dp))};Row(horizontalArrangement=Arrangement.spacedBy(4.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(totalInput,setTotal,label={Text("الإجمالي",fontSize=11.sp)},modifier=Modifier.weight(1f),shape=shape,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true,textStyle=LocalTextStyle.current.copy(fontSize=12.sp));OutlinedTextField(qty,setQty,label={Text("الكمية",fontSize=11.sp)},modifier=Modifier.weight(.72f),shape=shape,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true,textStyle=LocalTextStyle.current.copy(fontSize=12.sp));OutlinedTextField(itemName,setName,label={Text("التفاصيل",fontSize=11.sp)},modifier=Modifier.weight(1.65f),shape=shape,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Text),singleLine=true,textStyle=LocalTextStyle.current.copy(fontSize=12.sp));FilledIconButton(onClick={val total=totalInput.toDoubleOrNull()?:0.0;val q=qty.toDoubleOrNull()?:0.0;if(itemName.isNotBlank()&&q>0&&total>0){setRows(rows+SaleLine(itemName.trim(),q,total/q));setName("");setTotal("");setQty("1")}}){Icon(Icons.Default.Add,"إضافة",modifier=Modifier.size(19.dp))}};if(rows.isEmpty())Text("اختر صنفاً أو اكتب اسمه ثم أضفه",color=Color.Gray,fontSize=11.sp,modifier=Modifier.padding(5.dp));rows.forEachIndexed{index,line->Card(Modifier.fillMaxWidth().padding(vertical=2.dp)){Row(Modifier.padding(4.dp),verticalAlignment=Alignment.CenterVertically){Text(money(line.total),Modifier.weight(1f),fontSize=12.sp,fontWeight=FontWeight.Bold,textAlign=TextAlign.Center);Text(money(line.qty),Modifier.weight(.72f),fontSize=12.sp,textAlign=TextAlign.Center);Text(line.name,Modifier.weight(1.65f),fontSize=12.sp,fontWeight=FontWeight.Medium);IconButton(onClick={setRows(rows.filterIndexed{i,_->i!=index})}){Icon(Icons.Default.Delete,"حذف",modifier=Modifier.size(18.dp))}}}}}}
    Card(Modifier.fillMaxWidth().padding(vertical=5.dp)){Row(Modifier.padding(9.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Payments,null,modifier=Modifier.size(20.dp));Spacer(Modifier.width(6.dp));Column(Modifier.weight(1f)){Text("الإجمالي النهائي",fontSize=12.sp,fontWeight=FontWeight.Bold);Text("${money(grand)} ر.ي",fontWeight=FontWeight.Bold,fontSize=20.sp,color=PrimaryBlue)}}}
    Row(horizontalArrangement=Arrangement.spacedBy(3.dp),modifier=Modifier.fillMaxWidth()){Button(onClick=save,modifier=Modifier.weight(1f)){Icon(Icons.Default.Save,null,modifier=Modifier.size(18.dp));Spacer(Modifier.width(3.dp));Text("تأكيد الفاتورة",fontSize=11.sp)};OutlinedButton(onClick=print,modifier=Modifier.weight(.75f)){Icon(Icons.Default.Bluetooth,null,modifier=Modifier.size(18.dp));Text("طباعة",fontSize=10.sp)};IconButton(onClick=sharePdf){Icon(Icons.Default.PictureAsPdf,"PDF")};IconButton(onClick=shareWhatsApp){Icon(Icons.Default.Send,"واتساب")};IconButton(onClick=shareImage){Icon(Icons.Default.Image,"صورة")}}
}}

@Composable private fun StatCard(title:String,value:String,modifier:Modifier)=Card(modifier){Column(Modifier.padding(5.dp).fillMaxWidth(),horizontalAlignment=Alignment.CenterHorizontally){Text(title,fontSize=8.sp);Text(value,fontSize=14.sp,fontWeight=FontWeight.Bold)}}
@Composable private fun SectionTitle(icon:androidx.compose.ui.graphics.vector.ImageVector,title:String){Row(verticalAlignment=Alignment.CenterVertically){Icon(icon,null,modifier=Modifier.size(19.dp));Spacer(Modifier.width(4.dp));Text(title,fontWeight=FontWeight.Bold,fontSize=13.sp)}}

@Composable private fun HistoryScreen(list:List<InvoiceRow>,openPdf:(InvoiceRow)->Unit,openWhatsApp:(InvoiceRow)->Unit,excel:()->Unit){Column(Modifier.fillMaxSize().padding(9.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text("سجل الفواتير",fontSize=18.sp,fontWeight=FontWeight.Bold);IconButton(onClick=excel){Icon(Icons.Default.TableView,"Excel")}};LazyColumn{items(list){v->Card(Modifier.fillMaxWidth().padding(3.dp)){Row(Modifier.padding(9.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("فاتورة #${v.number}",fontWeight=FontWeight.Bold,fontSize=13.sp);Text(v.customer,fontSize=12.sp);Text("${v.date} ${v.time}",fontSize=10.sp)};Column(horizontalAlignment=Alignment.End){Text("${money(v.total)} ر.ي",fontWeight=FontWeight.Bold,fontSize=12.sp);Text(v.payment,fontSize=10.sp);Row{IconButton(onClick={openPdf(v)}){Icon(Icons.Default.PictureAsPdf,"PDF",modifier=Modifier.size(19.dp))};IconButton(onClick={openWhatsApp(v)}){Icon(Icons.Default.Send,"واتساب",modifier=Modifier.size(19.dp))}}}}}}}}}

@Composable private fun CustomersScreen(list:List<CustomerRow>,open:(CustomerRow)->Unit,new:()->Unit){Column(Modifier.fillMaxSize().padding(9.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text("العملاء والحسابات",fontSize=18.sp,fontWeight=FontWeight.Bold);FilledIconButton(onClick=new){Icon(Icons.Default.PersonAdd,"إضافة عميل")}};if(list.isEmpty())Text("لا يوجد عملاء بعد. أضف عميلاً أو استورده من جهات الاتصال.",color=Color.Gray,fontSize=12.sp,modifier=Modifier.padding(10.dp));LazyColumn{items(list){c->Card(Modifier.fillMaxWidth().padding(3.dp).clickable{open(c)}){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(c.name,fontWeight=FontWeight.Bold,fontSize=14.sp);Text(c.phone.ifBlank{"بدون جوال"},fontSize=11.sp)};Column(horizontalAlignment=Alignment.End){Text("${money(c.balance)} ر.ي",fontWeight=FontWeight.Bold,color=if(c.balance>0)Color(0xFFC62828)else Color(0xFF2E7D32));Text("فتح كشف الحساب",fontSize=10.sp,color=PrimaryBlue)}}}}}}}

@Composable private fun CustomerDialog(list:List<CustomerRow>,current:String,currentPhone:String,save:(String,String)->Unit,importContact:()->Unit,close:()->Unit){var name by remember(current){mutableStateOf(current)};var phone by remember(currentPhone){mutableStateOf(currentPhone)};AlertDialog(onDismissRequest=close,title={Text(if(current.isBlank()||current=="عميل نقدي")"إضافة عميل" else "العميل")},text={Column(Modifier.heightIn(max=440.dp)){Row(horizontalArrangement=Arrangement.spacedBy(6.dp),modifier=Modifier.fillMaxWidth()){OutlinedButton(onClick=importContact,modifier=Modifier.weight(1f)){Icon(Icons.Default.Contacts,null);Spacer(Modifier.width(4.dp));Text("من جهات الاتصال",fontSize=11.sp)}};OutlinedTextField(name,{name=it},label={Text("اسم العميل")},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Text),singleLine=true);OutlinedTextField(phone,{phone=it},label={Text("رقم الجوال / واتساب")},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Phone),singleLine=true);Spacer(Modifier.height(5.dp));if(list.isNotEmpty())Text("العملاء المحفوظون",fontWeight=FontWeight.Bold,fontSize=12.sp);LazyColumn{items(list.take(30)){c->ListItem(headlineContent={Text(c.name,fontSize=12.sp)},supportingContent={Text(c.phone.ifBlank{"بدون جوال"},fontSize=10.sp)},modifier=Modifier.clickable{name=c.name;phone=c.phone})}}}},confirmButton={Button(onClick={save(name,phone)}){Text("حفظ العميل")}},dismissButton={TextButton(onClick=close){Text("إلغاء")}})}

@Composable private fun LedgerDialog(act:Activity,db:AppDatabase,customer:CustomerRow,store:String,close:()->Unit){val scope=rememberCoroutineScope();var transactions by remember{mutableStateOf(emptyList<Array<String>>())};var customerInvoices by remember{mutableStateOf(emptyList<InvoiceRow>())};var amount by remember{mutableStateOf("")};fun accountText():String{val b=StringBuilder();b.append("العميل: ${customer.name}\nالجوال: ${customer.phone}\nالرصيد المستحق: ${money(customer.balance)} ر.ي\n\nالفواتير المرتبطة:\n");customerInvoices.forEach{b.append("#${it.number} - ${it.date} ${it.time} - ${money(it.total)} ر.ي - ${it.payment}\n")};b.append("\nالحركات والسداد:\n");transactions.forEach{b.append("${it[3]} ${it[4]} - ${it[2]} - ${money(it[1].toDoubleOrNull()?:0.0)} ر.ي\n")};return b.toString()};fun sharePdf(){val text=accountText();val u=NativeServices.pdf(act,"كشف_حساب_${safeName(customer.name)}","$store\n$text");NativeServices.share(act,u,"application/pdf",text)};fun shareImage(whatsapp:Boolean){val b=NativeServices.accountBitmap(store,customer,customerInvoices,transactions);val u=NativeServices.saveFile(act,b.pngBytes(),"كشف_حساب_${safeName(customer.name)}.png","image/png");if(whatsapp)NativeServices.shareWhatsApp(act,u,"image/png","كشف حساب ${customer.name} - الرصيد ${money(customer.balance)} ر.ي")else NativeServices.share(act,u,"image/png","كشف حساب ${customer.name}")};LaunchedEffect(customer.id){withContext(Dispatchers.IO){transactions=db.customerTransactions(customer.id);customerInvoices=db.customerInvoices(customer.name)}};AlertDialog(onDismissRequest=close,title={Text("حالة حساب ${customer.name}")},text={Column(Modifier.heightIn(max=500.dp)){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text("الرصيد المستحق",fontSize=11.sp);Text("${money(customer.balance)} ر.ي",fontSize=22.sp,fontWeight=FontWeight.Bold,color=if(customer.balance>0)Color(0xFFC62828)else Color(0xFF2E7D32));Text(customer.phone.ifBlank{"بدون رقم جوال"},fontSize=11.sp)}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(3.dp)){IconButton(onClick={sharePdf()}){Icon(Icons.Default.PictureAsPdf,"PDF")};IconButton(onClick={shareImage(false)}){Icon(Icons.Default.Image,"صورة")};IconButton(onClick={shareImage(true)}){Icon(Icons.Default.Send,"واتساب")};IconButton(onClick={val text=accountText();val u=NativeServices.pdf(act,"كشف_حساب_${safeName(customer.name)}",text);NativeServices.shareWhatsApp(act,u,"application/pdf",text)}){Icon(Icons.Default.Share,"إرسال واتساب PDF")}};Text("الفواتير المرتبطة: ${customerInvoices.size}",fontWeight=FontWeight.Bold,fontSize=12.sp);LazyColumn(Modifier.heightIn(max=180.dp)){items(customerInvoices){inv->ListItem(headlineContent={Text("فاتورة #${inv.number} — ${money(inv.total)} ر.ي",fontSize=12.sp)},supportingContent={Text("${inv.date} ${inv.time} • ${inv.payment}",fontSize=10.sp)})}};Text("الحركات والسداد",fontWeight=FontWeight.Bold,fontSize=12.sp);Row(verticalAlignment=Alignment.CenterVertically){OutlinedTextField(amount,{amount=it},label={Text("دفعة")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),modifier=Modifier.weight(1f),singleLine=true);IconButton(onClick={val value=amount.toDoubleOrNull()?:0.0;if(value>0)scope.launch(Dispatchers.IO){db.addPayment(customer.id,value,"سداد حساب",today(),now());val t=db.customerTransactions(customer.id);withContext(Dispatchers.Main){transactions=t;amount=""}}}){Icon(Icons.Default.Payment,"تسجيل دفعة")}};LazyColumn(Modifier.heightIn(max=150.dp)){items(transactions){row->ListItem(headlineContent={Text("${row[0]} — ${money(row[1].toDoubleOrNull()?:0.0)} ر.ي",fontSize=11.sp)},supportingContent={Text("${row[2]} • ${row[3]} ${row[4]}",fontSize=9.sp)})}}}},confirmButton={TextButton(onClick=close){Text("إغلاق")}})}

@Composable private fun InventoryScreen(list:List<ItemRow>,db:AppDatabase,refresh:()->Unit){val scope=rememberCoroutineScope();var selected by remember{mutableStateOf<ItemRow?>(null)};Column(Modifier.fillMaxSize().padding(9.dp)){Text("الأصناف والمخزون",fontSize=18.sp,fontWeight=FontWeight.Bold);Text("${list.size} صنف محفوظ",fontSize=11.sp,color=Color.Gray);LazyColumn{items(list){item->Card(Modifier.fillMaxWidth().padding(vertical=3.dp).clickable{selected=item}){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(item.name,fontWeight=FontWeight.Bold,fontSize=13.sp);Text("سعر الوحدة: ${money(item.price)} ر.ي",fontSize=10.sp)};Column(horizontalAlignment=Alignment.End){Text("المخزون ${money(item.stock)}",fontWeight=FontWeight.Bold,fontSize=12.sp);if(item.minStock>0&&item.stock<=item.minStock)Text("مخزون منخفض",color=Color(0xFFC62828),fontSize=10.sp)}}}}}};selected?.let{item->StockDialog(item,{delta->scope.launch(Dispatchers.IO){db.adjustStock(item.id,delta);withContext(Dispatchers.Main){selected=null;refresh()}}},{selected=null})}}
@Composable private fun StockDialog(item:ItemRow,apply:(Double)->Unit,close:()->Unit){var value by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("تعديل مخزون: ${item.name}")},text={Column{Text("المخزون الحالي: ${money(item.stock)}");OutlinedTextField(value,{value=it},label={Text("الكمية المضافة / المسحوبة")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal),singleLine=true);Text("اكتب + للزيادة أو - للنقص",fontSize=10.sp,color=Color.Gray)}},confirmButton={Button(onClick={value.toDoubleOrNull()?.let(apply)}){Text("تطبيق")}},dismissButton={TextButton(onClick=close){Text("إلغاء")}})}
@Composable private fun ReportsScreen(invoices:List<InvoiceRow>,customers:List<CustomerRow>,inventory:List<ItemRow>,store:String){val todayTotal=invoices.filter{it.date==today()}.sumOf{it.total};val debt=customers.sumOf{it.balance};val low=inventory.count{it.minStock>0&&it.stock<=it.minStock};Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(9.dp)){Text(store,fontSize=18.sp,fontWeight=FontWeight.Bold);Text("لوحة التقارير",fontSize=11.sp,color=Color.Gray);Spacer(Modifier.height(8.dp));ReportCard("مبيعات اليوم","${money(todayTotal)} ر.ي",Icons.Default.TrendingUp);ReportCard("إجمالي ديون العملاء","${money(debt)} ر.ي",Icons.Default.AccountBalanceWallet);ReportCard("الأصناف منخفضة المخزون",low.toString(),Icons.Default.Warning);ReportCard("عدد الفواتير",invoices.size.toString(),Icons.Default.ReceiptLong)}}
@Composable private fun ReportCard(title:String,value:String,icon:androidx.compose.ui.graphics.vector.ImageVector){Card(Modifier.fillMaxWidth().padding(vertical=3.dp)){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,modifier=Modifier.size(20.dp));Spacer(Modifier.width(8.dp));Column{Text(title,fontSize=10.sp);Text(value,fontSize=19.sp,fontWeight=FontWeight.Bold)}}}}
@Composable private fun SettingsDialog(name:String,phone:String,dark:Boolean,save:(String,String,Boolean)->Unit,printer:()->Unit,close:()->Unit){var store by remember(name){mutableStateOf(name)};var storePhone by remember(phone){mutableStateOf(phone)};var darkMode by remember(dark){mutableStateOf(dark)};AlertDialog(onDismissRequest=close,title={Text("إعدادات التطبيق")},text={Column(verticalArrangement=Arrangement.spacedBy(7.dp)){OutlinedTextField(store,{store=it},label={Text("اسم المتجر")},singleLine=true);OutlinedTextField(storePhone,{storePhone=it},label={Text("هاتف المتجر")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Phone),singleLine=true);Row(verticalAlignment=Alignment.CenterVertically){Text("الوضع الداكن",Modifier.weight(1f));Switch(checked=darkMode,onCheckedChange={darkMode=it})};OutlinedButton(onClick=printer,Modifier.fillMaxWidth()){Icon(Icons.Default.Bluetooth,null);Spacer(Modifier.width(5.dp));Text("إعداد الطابعة")};Text("الطباعة الحرارية: 58mm / Bluetooth",fontSize=10.sp,color=Color.Gray)}},confirmButton={Button(onClick={save(store,storePhone,darkMode)}){Text("حفظ")}},dismissButton={TextButton(onClick=close){Text("إلغاء")}})}
@Composable private fun PrinterDialog(list:List<BluetoothDevice>,close:()->Unit,select:(BluetoothDevice)->Unit){AlertDialog(onDismissRequest=close,title={Text("طابعة Bluetooth")},text={Column{if(list.isEmpty())Text("لا توجد طابعات مقترنة. فعّل Bluetooth ثم اقترن بالطابعة من إعدادات الهاتف.");list.forEach{device->ListItem(headlineContent={Text(device.name?:"طابعة حرارية")},supportingContent={Text(device.address)},modifier=Modifier.clickable{select(device)})}}},confirmButton={TextButton(onClick=close){Text("إغلاق")}})}
